'use client'

import { useEffect, useState } from 'react'

type User = {
  name: string
  email: string
  phone: string
  dob: string
  fullName: string
}

export default function ProfilePage() {
  const [user, setUser] = useState<User | null>(null)

  useEffect(() => {
    // Fetch user info dari API atau session
    const fetchProfile = async () => {
      const res = await fetch('/api/profile')
      if (res.ok) {
        const data = await res.json()
        setUser(data)
      }
    }

    fetchProfile()
  }, [])

  if (!user) {
    return <div className="p-6 text-center">Memuat profil...</div>
  }

  return (
    <div className="max-w-xl mx-auto p-6 mt-6 bg-white shadow-md rounded-lg">
      <h1 className="text-2xl font-bold text-emerald-700 mb-6 text-center">Profil Pengguna</h1>
      <div className="grid gap-4 text-sm text-gray-700">
        <ProfileField label="Nama Lengkap" value={user.fullName} />
        <ProfileField label="Nama Pengguna" value={user.name} />
        <ProfileField label="Email" value={user.email} />
        <ProfileField label="Nomor Telepon" value={user.phone} />
        <ProfileField label="Tanggal Lahir" value={user.dob} />
      </div>
    </div>
  )
}

function ProfileField({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex flex-col">
      <span className="text-gray-500 font-medium">{label}</span>
      <span className="text-gray-900">{value || '-'}</span>
    </div>
  )
}
